namespace Ordering;

/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            if (!TryCreateOrder(row, seen, out var order))
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static bool TryCreateOrder(string row, HashSet<string> seen, out Order order)
    {
        order = null!;

        if (string.IsNullOrWhiteSpace(row))
            return false;

        var parts = row.Split(',');
        if (parts.Length < 4)
            return false;

        var recordType = parts[0].Trim();
        var reference = parts[1].Trim();
        if (reference.Length == 0)
            return false;
        if (!seen.Add(reference))
            return false;

        if (!TryCreateOrderHeader(recordType, reference, out order))
            return false;

        AddOrderLines(parts, order);
        return order.Lines.Count > 0;
    }

    private static bool TryCreateOrderHeader(string recordType, string reference, out Order order)
    {
        switch (recordType)
        {
            case "H":
            case "ORDER":
                order = new Order { Reference = reference, Channel = OrderChannel.Web };
                return true;
            case "M":
                order = new Order { Reference = reference, Channel = OrderChannel.Marketplace };
                return true;
            default:
                order = null!;
                return false;
        }
    }

    private static void AddOrderLines(string[] parts, Order order)
    {
        for (int i = 2; i + 1 < parts.Length; i += 2)
        {
            if (!TryCreateOrderLine(parts[i], parts[i + 1], out var line))
                continue;

            order.Lines.Add(line);
        }
    }

    private static bool TryCreateOrderLine(string skuPart, string quantityPart, out OrderLine line)
    {
        line = null!;

        var sku = skuPart.Trim();
        if (sku.Length == 0)
            return false;

        if (!int.TryParse(quantityPart, out var qty) || qty <= 0)
            return false;

        line = new OrderLine
        {
            Sku = sku,
            Quantity = qty,
            UnitPrice = CalculateUnitPrice(sku, qty)
        };

        return true;
    }

    private static decimal CalculateUnitPrice(string sku, int qty)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && qty > 10)
            return 9.99m;

        if (sku.StartsWith("STD", StringComparison.Ordinal))
            return 4.99m;

        return 0m;
    }
}
